#!/usr/bin/env bash
#
# PocketPills — recover ALL medicines from handwritten prescriptions.
# Applies on top of commit 86eb3eb (the v1 lexicon fix you already pushed).
#
#  1. lineSegments.ts — ADAPTIVE row-ink threshold. This is the reason only two
#     medicines appeared: a fixed 1.2%-of-page-width cut required ~19 dark
#     pixels per row, and a short faint line ("T. Placida 1 OD") yields ~17, so
#     three medicines were DELETED before recognition ever ran.
#  2. rxLexicon.ts — brand anchoring. Finds the known brand inside a noisy line
#     and rebuilds the name outward: "Gp Razo Po" -> "Razo",
#     "IE Ambulax I" -> "Ambulax". Fuzzy tolerance now scales with word length
#     and tolerates 0/O, 1/l, 5/S, 8/B confusions.
#  3. rxLexicon.ts — strengths must sit NEXT TO the name. Scanning the whole
#     line fabricated "8mg" on Ambulax from a garbled "1 BD".
#  4. rxOcr.ts — one parseRxLine path, plus a debug switch:
#       localStorage.setItem("pp:rx-debug","1")
#     Rescan and the console prints the raw OCR text and a keep/skip reason for
#     every line, so you can tell recognition failures from parser failures.
#
# Safe to re-run. Backs up touched files; verifies with tsc + vite build.
#
set -euo pipefail

grep -q '"pocketpills-redesign"' package.json 2>/dev/null || {
  echo "!! Run from the pocketpills repo root."; exit 1; }
[ -f src/lib/rxLexicon.ts ] || {
  echo "!! Expected src/lib/rxLexicon.ts (the v1 fix). Pull latest first."; exit 1; }

BK=".rxfix2-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "${BK}/src/lib/localHtr"
echo ">> Backups -> ${BK}/"
cp src/lib/rxOcr.ts src/lib/rxLexicon.ts "${BK}/src/lib/"
cp src/lib/localHtr/lineSegments.ts "${BK}/src/lib/localHtr/"

if grep -q "anchorBrandName" src/lib/rxLexicon.ts; then
  echo ">> Already patched — skipping"
else
  echo ">> Patching rxLexicon.ts + rxOcr.ts + lineSegments.ts"
  PATCH=""
  if printf '%s' "$PATCH" | base64 -d | git apply -p1 --check - 2>/dev/null; then
    printf '%s' "$PATCH" | base64 -d | git apply -p1 -; echo "   applied via git apply"
  elif printf '%s' "$PATCH" | base64 -d | patch -p1 --dry-run >/dev/null 2>&1; then
    printf '%s' "$PATCH" | base64 -d | patch -p1; echo "   applied via patch"
  else
    echo "!! Did not apply cleanly — your files differ from commit 86eb3eb."
    echo "   Backup at ${BK}."; exit 2
  fi
fi

echo ">> Verifying (tsc)"; npx tsc -b --noEmit
echo ">> Verifying (vite build)"; npx vite build >/dev/null
echo ""
echo "Done. Backup: ${BK}"
echo "Debug a scan:  localStorage.setItem('pp:rx-debug','1')  then rescan."
echo "Rollback: cp -r ${BK}/src ./"
